// AQA GCSE Physics 8463 (also covers the physics in Combined Science Trilogy 8464) + KS3 physics foundations.
// Format: docs/SUBJECT_FORMAT.md.  Zero dependencies.

// ---------- item helpers ----------
const mcq = (q, options, correct, explain, hint) => ({ type: 'mcq', q, options, correct, explain, hint });
const multi = (q, options, correct, explain, hint) => ({ type: 'multi', q, options, correct, explain, hint });
const tf = (q, correct, explain, hint) => ({ type: 'tf', q, correct, explain, hint });
const sh = (q, answer, accept, explain, keywords, hint) => ({ type: 'short', q, answer, accept: [answer, ...accept], keywords, explain, hint });
const ord = (q, options, explain, hint) => ({ type: 'order', q, options, explain, hint });
const num = (q, value, unit, steps, explain, hint) => ({ type: 'number', q, value, tol: Math.abs(value) * 0.01 + 1e-9, unit, answer: `${fmt(value)} ${unit}`.trim(), steps, explain, hint });

// ---------- generator helpers ----------
const pick = (rng, a) => a[Math.floor(rng() * a.length)];
const ri = (rng, lo, hi) => lo + Math.floor(rng() * (hi - lo + 1));
const rstep = (rng, lo, hi, step) => Number((lo + step * Math.floor(rng() * (Math.round((hi - lo) / step) + 1))).toFixed(6));
function sf(x) { return Math.abs(x - Math.round(x)) < 1e-9 ? Math.round(x) : Number(x.toPrecision(3)); }
function fmt(x) { return Number(x).toLocaleString('en-GB', { maximumFractionDigits: 6 }); }
// Builds a calculation question with steps formula → (rearrange) → substitute → answer with unit.
function calc({ q, formula, rearr, sub, value, unit, explain, hint }) {
  const v = sf(value);
  const steps = [`Write the equation: ${formula}`];
  if (rearr) steps.push(`Rearrange for the unknown: ${rearr}`);
  steps.push(`Substitute the values: ${sub}`);
  steps.push(`Answer: <b>${fmt(v)} ${unit}</b>`);
  return { type: 'number', q, value: v, tol: Math.abs(v) * 0.01 + 1e-9, unit, answer: `${fmt(v)} ${unit}`, steps,
    explain: explain || `Use ${formula}, put the numbers in with SI units, and give the unit with your answer.`, hint: hint || `Start from ${formula}.` };
}

// ---------- module assembly ----------
const topics = [];
const styles = {};
const learn = {};
function addTopic(t, styleDefs, L) {
  t.styles = [];
  styleDefs.forEach((s, i) => {
    const id = `${t.id}-${i + 1}`;
    t.styles.push(id);
    styles[id] = Object.assign({ id, topicId: t.id }, s);
  });
  topics.push(t);
  learn[t.id] = Object.assign({ specRef: t.specRef }, L);
}

